import json
import re
import uuid

from framework_evidence import run_tool

HOST = "192.168.5.9"


def invoke(argv, records, label):
    try:
        result = run_tool(argv)
        records.append({"label": label, "envelope": result})
        if isinstance(result, dict):
            return result.get("stdout", "") or ""
        return ""
    except Exception as exc:
        records.append({"label": label, "error": type(exc).__name__ + ": " + str(exc)})
        return ""


def disk_shares(output):
    found = []
    for line in output.splitlines():
        fields = line.split("|", 2)
        if len(fields) >= 2 and fields[0].strip().lower() == "disk":
            name = fields[1].strip()
            if name and name not in found:
                found.append(name)
    # Retain support for smbclient's human-readable listing if -g output differs.
    if not found:
        for line in output.splitlines():
            match = re.match(r"^\s*(\S+)\s+Disk(?:\s|$)", line, re.IGNORECASE)
            if match and match.group(1).upper() != "IPC$":
                name = match.group(1)
                if name not in found:
                    found.append(name)
    return [name for name in found if name.upper() != "IPC$"]


records = []
checks = []
routes = [
    {"name": "anonymous", "auth": ["-U", "%"]},
    {"name": "guest", "auth": ["-U", "guest%"]},
]

for route in routes:
    listing_argv = ["smbclient", "-g", "-L", "//" + HOST] + route["auth"]
    listing_output = invoke(listing_argv, records, route["name"] + " share enumeration")
    shares = disk_shares(listing_output)
    route_result = {"route": route["name"], "listed_disk_shares": shares, "share_checks": []}

    for share in shares:
        share_ref = "//" + HOST + "/" + share
        ls_argv = ["smbclient", share_ref] + route["auth"] + ["-c", "ls"]
        ls_output = invoke(ls_argv, records, route["name"] + " list " + share)
        accessible = False
        # Successful SMB directory listing is evidence of access; exit status is retained.
        last = records[-1].get("envelope", {}) if records else {}
        if isinstance(last, dict):
            accessible = last.get("exit_code") == 0

        share_result = {
            "share": share,
            "directory_listing_exit_zero": accessible,
            "write_probe": "not attempted because share listing did not complete successfully",
            "observed_path_scope": None,
        }
        if accessible:
            probe = ".smb_access_probe_" + uuid.uuid4().hex
            put_argv = ["smbclient", share_ref] + route["auth"] + ["-c", "put /dev/null " + probe]
            invoke(put_argv, records, route["name"] + " write probe " + share)
            put_envelope = records[-1].get("envelope", {}) if records else {}
            put_ok = isinstance(put_envelope, dict) and put_envelope.get("exit_code") == 0
            if put_ok:
                share_result["write_probe"] = "temporary file upload succeeded"
                share_result["observed_path_scope"] = "share root (relative path .); physical backing path not established"
                rm_argv = ["smbclient", share_ref] + route["auth"] + ["-c", "del " + probe]
                invoke(rm_argv, records, route["name"] + " remove write probe " + share)
                rm_envelope = records[-1].get("envelope", {}) if records else {}
                share_result["probe_cleanup_exit_zero"] = isinstance(rm_envelope, dict) and rm_envelope.get("exit_code") == 0
            else:
                share_result["write_probe"] = "temporary file upload did not complete successfully"
        route_result["share_checks"].append(share_result)
    checks.append(route_result)

print(json.dumps({
    "target": HOST,
    "credential_evidence": "No established credentials are supplied in the visible, truncated observation preview; no credentials were guessed. Anonymous and guest routes were tested.",
    "checks": checks,
    "tool_runs": records,
    "interpretation_note": "A failed or incomplete tool run does not establish that SMB access or prerequisites are absent. SMB share enumeration does not reveal the share's physical server-side filesystem path."
}, ensure_ascii=False))

